1	import {
2	  INPUT_HOLD_FRAMES,
3	  MAX_INPUT_MESSAGES_PER_SECOND,
4	  validateInputMessage,
5	  type InputRejection,
6	} from "@pirate-sea-race/protocol";
7	import { NEUTRAL_INPUT, quantizeAxis, STEPS_PER_SECOND, type PlayerInput } from "@pirate-sea-race/simulation";
8	
9	export type DropReason = InputRejection | "rate-limited";
10	
11	/**
12	 * One client's input channel on the server: it admits messages under the rate cap, validates them against the
13	 * protocol and the client's last sequence, and holds the latest accepted intent for the simulation. A held input
14	 * lapses to neutral when no fresh one arrives within INPUT_HOLD_FRAMES (§15).
15	 */
16	export class InputGate {
17	  private lastAcceptedSeq = 0;
18	  private held: PlayerInput = NEUTRAL_INPUT;
19	  private heldAtFrame = 0;
20	  private windowStart = 0;
21	  private windowCount = 0;
22	  readonly dropped: Record<DropReason, number> = {
23	    "rate-limited": 0,
24	    oversized: 0,
25	    malformed: 0,
26	    "stale-sequence": 0,
27	    "future-frame": 0,
28	  };
29	
30	  /** Takes one untrusted message at the server's current frame. Returns why it was dropped, or undefined. */
31	  receive(message: unknown, serverFrame: number): DropReason | undefined {
32	    if (serverFrame - this.windowStart >= STEPS_PER_SECOND) {
33	      this.windowStart = serverFrame;
34	      this.windowCount = 0;
35	    }
36	    if (++this.windowCount > MAX_INPUT_MESSAGES_PER_SECOND) return this.drop("rate-limited");
37	    const result = validateInputMessage(message, { lastAcceptedSeq: this.lastAcceptedSeq, serverFrame });
38	    if (!result.ok) return this.drop(result.reason);
39	    this.lastAcceptedSeq = result.input.seq;
40	    this.held = {
41	      buttons: result.input.buttons,
42	      moveX: quantizeAxis(result.input.moveX),
43	      moveY: quantizeAxis(result.input.moveY),
44	    };
45	    this.heldAtFrame = serverFrame;
46	    return undefined;
47	  }
48	
49	  /** The intent the simulation uses for `frame`. */
50	  inputAt(frame: number): PlayerInput {
51	    return frame - this.heldAtFrame > INPUT_HOLD_FRAMES ? NEUTRAL_INPUT : this.held;
52	  }
53	
54	  private drop(reason: DropReason): DropReason {
55	    this.dropped[reason]++;
56	    return reason;
57	  }
58	}
59

