1	/** Movement axes enter the simulation as integers in [-AXIS_SCALE, AXIS_SCALE]. */
2	export const AXIS_SCALE = 1000;
3	
4	/** One player's held intent for a step. `buttons` is a bit field; this feature uses movement only. */
5	export interface PlayerInput {
6	  readonly buttons: number;
7	  readonly moveX: number;
8	  readonly moveY: number;
9	}
10	
11	export const NEUTRAL_INPUT: PlayerInput = { buttons: 0, moveX: 0, moveY: 0 };
12	
13	/** Turns a protocol axis in [-1, 1] into simulation units. Out-of-range values clamp; anything non-finite is 0. */
14	export function quantizeAxis(axis: number): number {
15	  if (!Number.isFinite(axis)) return 0;
16	  const clamped = axis < -1 ? -1 : axis > 1 ? 1 : axis;
17	  return Math.round(clamped * AXIS_SCALE);
18	}
19	
20	/** Keeps a simulation input inside its integer bounds whatever the caller passed. */
21	export function sanitizeInput(input: PlayerInput | undefined): PlayerInput {
22	  if (input === undefined) return NEUTRAL_INPUT;
23	  const axis = (value: number) =>
24	    Number.isInteger(value) ? Math.max(-AXIS_SCALE, Math.min(AXIS_SCALE, value)) : 0;
25	  return {
26	    buttons: Number.isInteger(input.buttons) ? input.buttons >>> 0 : 0,
27	    moveX: axis(input.moveX),
28	    moveY: axis(input.moveY),
29	  };
30	}
