1	import { describe, expect, it } from "vitest";
2	import {
3	  AXIS_SCALE,
4	  addShip,
5	  createMatchState,
6	  defaultSimulationConfig as config,
7	  hashState,
8	  isqrt,
9	  mapBounds,
10	  quantizeAxis,
11	  removeShip,
12	  step,
13	  toTilePosition,
14	  WORLD_STEP_INTERVAL,
15	  type MatchState,
16	  type PlayerInput,
17	} from "./index.js";
18	
19	interface LoggedInput {
20	  readonly frame: number;
21	  readonly shipId: string;
22	  readonly input: PlayerInput;
23	}
24	
25	/** Replays an input log: each entry becomes that ship's held input from its frame on. */
26	function run(initial: MatchState, log: readonly LoggedInput[], steps: number): MatchState {
27	  let state = initial;
28	  const held: Record<string, PlayerInput> = {};
29	  for (let index = 0; index < steps; index++) {
30	    const frame = state.frame + 1;
31	    for (const entry of log) if (entry.frame === frame) held[entry.shipId] = entry.input;
32	    state = step(config, state, held);
33	  }
34	  return state;
35	}
36	
37	function matchWithShips(seed: number, ids: readonly string[]): MatchState {
38	  return ids.reduce((state, id) => addShip(config, state, id), createMatchState(seed));
39	}
40	
41	const move = (moveX: number, moveY: number): PlayerInput => ({ buttons: 0, moveX, moveY });
42	
43	const inputLog: LoggedInput[] = [
44	  { frame: 1, shipId: "a", input: move(AXIS_SCALE, 0) },
45	  { frame: 10, shipId: "b", input: move(0, -AXIS_SCALE) },
46	  { frame: 90, shipId: "a", input: move(AXIS_SCALE, AXIS_SCALE) },
47	  { frame: 200, shipId: "c", input: move(-600, 300) },
48	  { frame: 320, shipId: "b", input: move(0, 0) },
49	  { frame: 450, shipId: "a", input: move(-AXIS_SCALE, 0) },
50	];
51	
52	describe("determinism", () => {
53	  it("gives the same hash for the same initial state and input log after 600 steps", () => {
54	    const first = run(matchWithShips(1234, ["a", "b", "c"]), inputLog, 600);
55	    const second = run(matchWithShips(1234, ["a", "b", "c"]), inputLog, 600);
56	    expect(first.frame).toBe(600);
57	    expect(hashState(first)).toBe(hashState(second));
58	    expect(first).toEqual(second);
59	  });
60	
61	  it("gives a different hash when one input changes", () => {
62	    const changed = inputLog.map((entry, index) => (index === 3 ? { ...entry, input: move(-600, -300) } : entry));
63	    const original = run(matchWithShips(1234, ["a", "b", "c"]), inputLog, 600);
64	    const altered = run(matchWithShips(1234, ["a", "b", "c"]), changed, 600);
65	    expect(hashState(altered)).not.toBe(hashState(original));
66	  });
67	
68	  it("hashes the complete state, including the generator", () => {
69	    const state = matchWithShips(1, ["a"]);
70	    expect(hashState({ ...state, rng: state.rng + 1 })).not.toBe(hashState(state));
71	    expect(hashState({ ...state, frame: 1 })).not.toBe(hashState(state));
72	  });
73	
74	  it("does not depend on key order", () => {
75	    const state = matchWithShips(99, ["a", "b"]);
76	    const reordered = { ships: state.ships.map((ship) => ({ ...ship })).map((ship) => {
77	      const { heading, vy, vx, y, x, slot, id } = ship;
78	      return { heading, vy, vx, y, x, slot, id };
79	    }), rng: state.rng, worldTick: state.worldTick, frame: state.frame };
80	    expect(hashState(reordered)).toBe(hashState(state));
81	  });
82	
83	  it("keeps every number in the state an integer", () => {
84	    const state = run(matchWithShips(7, ["a", "b", "c"]), inputLog, 600);
85	    for (const ship of state.ships) {
86	      for (const value of [ship.x, ship.y, ship.vx, ship.vy, ship.heading, ship.slot]) expect(Number.isInteger(value)).toBe(true);
87	    }
88	  });
89	
90	  it("does not mutate the state it is given", () => {
91	    const state = Object.freeze(matchWithShips(5, ["a"]));
92	    expect(() => step(config, state, { a: move(AXIS_SCALE, 0) })).not.toThrow();
93	    expect(state.frame).toBe(0);
94	  });
95	});
96	
97	describe("clock", () => {
98	  it("advances world logic only on every third step", () => {
99	    let state = matchWithShips(42, ["a"]);
100	    const start = state.ships[0]!;
101	    const inputs = { a: move(AXIS_SCALE, 0) };
102	    for (let frame = 1; frame <= 30; frame++) {
103	      const before = state;
104	      state = step(config, state, inputs);
105	      expect(state.frame).toBe(frame);
106	      if (frame % WORLD_STEP_INTERVAL === 0) {
107	        expect(state.worldTick).toBe(before.worldTick + 1);
108	        expect(state.ships[0]!.x).toBeGreaterThan(before.ships[0]!.x);
109	      } else {
110	        expect(state.worldTick).toBe(before.worldTick);
111	        expect(state.ships).toBe(before.ships);
112	      }
113	    }
114	    expect(state.worldTick).toBe(10);
115	    expect(state.ships[0]!.x - start.x).toBe(10 * config.ship.speedSubUnitsPerWorldStep);
116	  });
117	});
118	
119	describe("movement", () => {
120	  it("normalises diagonals with integer maths", () => {
121	    const state = step(config, step(config, step(config, matchWithShips(3, ["a"]), {}), {}), { a: move(AXIS_SCALE, AXIS_SCALE) });
122	    const ship = state.ships[0]!;
123	    const speed = config.ship.speedSubUnitsPerWorldStep;
124	    expect(ship.vx).toBe(ship.vy);
125	    expect(isqrt(ship.vx * ship.vx + ship.vy * ship.vy)).toBeLessThanOrEqual(speed);
126	    expect(ship.vx).toBe(Math.trunc((speed * AXIS_SCALE) / isqrt(2 * AXIS_SCALE * AXIS_SCALE)));
127	  });
128	
129	  it("clamps ships to the map bounds", () => {
130	    const state = run(matchWithShips(3, ["a"]), [{ frame: 1, shipId: "a", input: move(-AXIS_SCALE, -AXIS_SCALE) }], 60 * 30);
131	    const ship = state.ships[0]!;
132	    expect(ship.x).toBe(0);
133	    expect(ship.y).toBe(0);
134	    const far = run(matchWithShips(3, ["a"]), [{ frame: 1, shipId: "a", input: move(AXIS_SCALE, AXIS_SCALE) }], 60 * 30);
135	    expect(far.ships[0]!.x).toBe(mapBounds(config).maxX);
136	    expect(far.ships[0]!.y).toBe(mapBounds(config).maxY);
137	    const corner = toTilePosition(config, far.ships[0]!.x, far.ships[0]!.y);
138	    expect(corner.tileX).toBe(config.map.widthTiles - 1);
139	    expect(corner.tileY).toBe(config.map.heightTiles - 1);
140	  });
141	
142	  it("treats an out-of-range simulation axis as clamped", () => {
143	    const wild = step(config, step(config, step(config, matchWithShips(3, ["a"]), {}), {}), { a: move(50 * AXIS_SCALE, 0) });
144	    expect(wild.ships[0]!.vx).toBe(config.ship.speedSubUnitsPerWorldStep);
145	  });
